 <div className="art:flex art:min-h-0 art:flex-1 art:flex-col art:justify-between art:overflow-hidden art:p-5 art:@min-[640px]/artemis:p-7"><div><p className="art:text-xs art:font-medium art:text-muted-foreground">Focus workspace</p><h3 className="art:mt-2 art:max-w-lg art:text-xl art:font-medium art:tracking-tight">Everything important, without nested navigation.</h3><p className="art:mt-2 art:max-w-lg art:text-sm art:leading-6 art:text-muted-foreground">Collapse the sidebar to give the active workspace the full canvas. The navigation returns from the same edge when needed.</p></div><div className="art:grid art:gap-3 art:@min-[640px]/artemis:grid-cols-2">{[{ label: "Open projects", value: "18" }, { label: "Updates today", value: "32" }].map(item => <div key={item.label} className="art:rounded-xl art:border art:border-border art:bg-background art:p-5"><p className="art:text-xs art:text-muted-foreground">{item.label}</p><p className="art:mt-5 art:text-2xl art:font-semibold">{item.value}</p></div>)}</div></div>
 </ArtemisSidebarFrame>;
