"use client";
// @zeus-internal
import { Inbox, FolderKanban, CalendarDays, FileText, ChartNoAxesCombined, Users, Settings } from "lucide-react";
import { ArtemisSidebarNavigation } from "../../../../lib/sidebar-navigation";
export const pages = [{ name: "Inbox", icon: Inbox, count: "12" }, { name: "Projects", icon: FolderKanban }, { name: "Calendar", icon: CalendarDays }, { name: "Documents", icon: FileText }, { name: "Analytics", icon: ChartNoAxesCombined }, { name: "Members", icon: Users }, { name: "Settings", icon: Settings }] as const;
export function OffcanvasNavigation(props: {
    selected: string;
    collapsed: boolean;
    onSelect: (name: string) => void;
}) { return <ArtemisSidebarNavigation {...props} pages={pages} label="Navigation" hoverTransition={{ type: "spring", stiffness: 205, damping: 22, mass: 1 }}/>; }

"use client";
// @zeus-internal
import { ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
