import { WorkspaceMenu } from "./workspace-menu";
import { OffcanvasSearch } from "./search";
import { OffcanvasNavigation } from "./navigation";
import { PANEL_TRANSITION, REDUCED_TRANSITION } from "./transitions";
export function OffcanvasPanel({ collapsed, mobile, selected, workspace, onSelect, onSearchSelect, onWorkspace, onClose }: {
    collapsed: boolean;
    mobile: boolean;
    selected: string;
    workspace: string;
    onSelect: (name: string) => void;
    onWorkspace: (name: string) => void;
    onSearchSelect: (name: string) => void;
    onClose: () => void;
}) {
    const reduceMotion = useReducedMotion();
    const [menuOpen, setMenuOpen] = useState(false);
    const [keyboardMenu, setKeyboardMenu] = useState(false);
    const [immediateHighlight, setImmediateHighlight] = useState(false);
    const menuBase = `radix-${useId()}`;
    const triggerId = `${menuBase}-workspace-trigger`;
    const contentId = `${menuBase}-workspace-content`;
    const switchRef = useRef<HTMLButtonElement>(null);
    const chooseWorkspace = (name: string) => { onWorkspace(name); setMenuOpen(false); };
    const body = (<>
              <div data-slot="sidebar-header" className="art:flex art:shrink-0 art:flex-col art:gap-2 art:p-3 art:pb-2">
                <div className="art:flex art:min-h-11 art:items-center art:gap-2 art:px-2">
                  <motion.button type="button" ref={switchRef} id={triggerId} aria-controls={menuOpen ? contentId : undefined} data-radix-popper-side={menuOpen ? "bottom" : undefined} data-radix-popper-align={menuOpen ? "start" : undefined} whileHover={reduceMotion ? undefined : { scale: 1.01 }} whileTap={reduceMotion ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onPointerDown={event => {
            if (event.button !== 0 || event.ctrlKey)
                return;
            if (!menuOpen)
                event.preventDefault();
            event.currentTarget.removeAttribute("data-artemis-pointer-focus");
            setKeyboardMenu(false);
            setImmediateHighlight(false);
            setMenuOpen(open => !open);
        }} onKeyDown={event => {
            event.currentTarget.removeAttribute("data-artemis-pointer-focus");
            if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                setKeyboardMenu(true);
                setImmediateHighlight(event.key === " ");
                setMenuOpen(open => !open);
            }
            else if (event.key === "ArrowDown") {
                event.preventDefault();
                setKeyboardMenu(true);
                setImmediateHighlight(false);
                setMenuOpen(true);
            }
        }} onBlur={event => event.currentTarget.removeAttribute("data-artemis-pointer-focus")} className="art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:text-inherit art:hover:bg-muted art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:group art:flex art:min-w-0 art:flex-1 art:items-center art:gap-3 art:text-left art:outline-none art:rounded-full" aria-label={`Switch workspace, current workspace ${workspace}`} aria-haspopup="menu" aria-expanded={menuOpen} data-state={menuOpen ? "open" : "closed"} tabIndex={0}>
                    <span className="art:grid art:size-8 art:shrink-0 art:place-items-center art:bg-foreground art:text-background art:rounded-full">
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-command art:size-4" aria-hidden="true">
                        <path d="M15 6v12a3 3 0 1 0 3-3H6a3 3 0 1 0 3 3V6a3 3 0 1 0-3 3h12a3 3 0 1 0-3-3"/>
                      </svg>
                    </span>
                    <span className="art:min-w-0 art:flex-1 art:truncate art:font-semibold art:text-foreground art:text-sm">
                      {workspace}
                    </span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevrons-up-down art:size-3.5 art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                      <path d="m7 15 5 5 5-5"/>
                      <path d="m7 9 5-5 5 5"/>
                    </svg>
                  </motion.button>
                  <button type="button" onClick={onClose} aria-label="Close sidebar" className="art:inline-flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-xl art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:text-muted-foreground art:hover:bg-muted art:@min-[768px]/artemis:hidden">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-4" aria-hidden="true">
                      <path d="M18 6 6 18"/>
                      <path d="m6 6 12 12"/>
                    </svg>
                  </button>
                </div>
              </div>
              <div data-slot="sidebar-content" className="art:flex art:min-h-0 art:flex-1 art:flex-col art:gap-2 art:overflow-y-auto art:overflow-x-hidden art:overscroll-contain art:py-2 art:px-2 art:pt-2">
                <div data-slot="sidebar-group" className="art:flex art:w-full art:min-w-0 art:flex-col art:px-1 art:py-1.5 art:pb-3">
                  <div data-slot="sidebar-group-content" className="art:w-full art:min-w-0">
                    <ArtemisSharedLayoutBg as="ul" data-slot="sidebar-menu" inset={0} pillClassName="art:rounded-xl art:bg-muted/70" pillContainerClassName="art:inset-y-auto art:top-0 art:h-9" className="art:flex art:w-full art:min-w-0 art:list-none art:flex-col art:gap-0.5">
                      <li key="search" data-slot="sidebar-menu-item" className="art:relative">
                          <OffcanvasSearch onSelect={onSearchSelect}/>
                      </li>
                    </ArtemisSharedLayoutBg>
                  </div>
                </div>
                <OffcanvasNavigation selected={selected} collapsed={collapsed} onSelect={onSelect}/>
              </div>
              <div data-slot="sidebar-footer" className="art:flex art:shrink-0 art:flex-col art:gap-2 art:border-border art:border-t art:border-none art:p-3">
                <div className="art:relative art:flex art:min-h-11 art:w-full art:items-center art:gap-3 art:rounded-xl art:p-1 art:text-left art:transition-colors art:hover:bg-muted art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring art:has-[:focus-visible]:ring-offset-2 art:has-[:focus-visible]:ring-offset-background">
                  <span className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:bg-primary/10 art:font-semibold art:text-primary art:text-xs">
                    {"RE"}
                  </span>
                  <span className="art:min-w-0 art:flex-1">
                    <span className="art:block art:truncate art:font-medium art:text-foreground art:text-sm">
                      {"Robin Ellis"}
                    </span>
                    <span className="art:block art:truncate art:text-muted-foreground art:text-xs">
                      {"member@example.com"}
                    </span>
                  </span>
                <button type="button" aria-label="Robin Ellis" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-ring art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:size-full art:cursor-pointer art:outline-none art:focus-visible:ring-0 art:focus-visible:ring-offset-0 art:rounded-full"/>
                </div>
              </div>
  </>);
    return <>
    {mobile ? body : <motion.div className="art:sticky art:top-0 art:flex art:flex-col art:overflow-hidden art:w-[var(--artemis-sidebar-width)] art:border-r art:h-full art:border-foreground/[0.08] art:bg-muted/25" initial={false} animate={{ opacity: collapsed ? 0 : 1, x: reduceMotion ? 0 : collapsed ? "-100%" : "0%" }} transition={reduceMotion ? REDUCED_TRANSITION : PANEL_TRANSITION}>{body}</motion.div>}
    <WorkspaceMenu contentId={contentId} keyboardOpen={keyboardMenu} immediateHighlight={immediateHighlight} open={menuOpen} triggerRef={switchRef} selected={workspace} onSelect={chooseWorkspace} onClose={() => setMenuOpen(false)}/>
  </>;
}

"use client";
// @zeus-internal
import { Inbox, FolderKanban, CalendarDays, FileText, ChartNoAxesCombined, Users, Settings } from "lucide-react";
import { MorphingSearch, type MorphingSearchItem } from "./morphing-search";
const items: MorphingSearchItem[] = [
    { id: "inbox", title: "Inbox", icon: Inbox, description: "Navigation", keywords: ["messages", "updates"] },
    { id: "projects", title: "Projects", icon: FolderKanban, description: "Navigation", keywords: ["work", "board"] },
    { id: "calendar", title: "Calendar", icon: CalendarDays, description: "Navigation", keywords: ["schedule", "events"] },
    { id: "documents", title: "Documents", icon: FileText, description: "Navigation", keywords: ["files", "notes"] },
    { id: "analytics", title: "Analytics", icon: ChartNoAxesCombined, description: "Navigation", keywords: ["reports", "usage"] },
    { id: "members", title: "Members", icon: Users, description: "Navigation", keywords: ["team", "people"] },
    { id: "settings", title: "Settings", icon: Settings, description: "Navigation", keywords: ["preferences", "billing"] },
];
export function OffcanvasSearch({ onSelect }: {
