    select(id === null ? null : { key: id, session: committed.current.query });
  }, []);
  const moveActive = useCallback((direction: 1 | -1) => {
    select(previous => {
      const { rows: choices, query: session } = committed.current;
      if (!choices.length) return previous;
      const position = previous?.session === session ? choices.findIndex(row => row.id === previous.key) : -1;
      const next = Math.max(0, Math.min(choices.length - 1, Math.max(0, position) + direction));
